}

/* ---------- Thinking shimmer ---------- */

/**
 * "Thinking" with a band of light sweeping across it, over three skeleton lines.
 * The band is a window that slides right while the accent copy inside it slides left by
 * the same amount, so the copy stays exactly over the real letters (transform only).
 * Driven imperatively (WAAPI transforms): it stays smooth while replies re-render, and an
 * ancestor's AnimatePresence initial={false} can't freeze it.
 */
export function Thinking({ label, reduced }: { label: string; reduced: boolean }) {
  const windowRef = useRef<HTMLSpanElement>(null);
  const copyRef = useRef<HTMLSpanElement>(null);
  const barsRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (reduced) return;
    // Short sweeps so the band crosses the word early. Native WAAPI loop (compositor transform): the pause
    // between sweeps is baked into the keyframes (offset 0.85), so no JS ticks and no `repeatDelay`.
    const sweep = (el: HTMLElement | null, from: string, to: string, delay = 0) =>
      el?.animate([{ transform: from }, { transform: to, offset: 0.85 }, { transform: to }], {
        duration: 1350,
        easing: `cubic-bezier(${ease.inOut.join(",")})`,
        iterations: Infinity,
        delay,
        fill: "backwards",
      });
    const bars = Array.from(barsRef.current?.querySelectorAll<HTMLElement>("[data-sweep]") ?? []);
    const controls = [
      sweep(windowRef.current, "translateX(-100%)", "translateX(250%)"),
      sweep(copyRef.current, "translateX(40%)", "translateX(-100%)"),
      ...bars.map((bar, i) => sweep(bar, "translateX(-100%)", "translateX(200%)", i * 120)),
    ];
    return () => controls.forEach((c) => c?.cancel());
  }, [reduced]);

  return (
    <div className="flex flex-col gap-3 pt-1">
      <span className="relative inline-flex w-fit overflow-clip text-sm leading-7 font-medium whitespace-nowrap text-sheen-fg-muted">
        {label}
        {!reduced && (
          <span
            ref={windowRef}
            aria-hidden
            style={{ transform: "translateX(-100%)" }}
            className="pointer-events-none absolute inset-y-0 left-0 w-2/5 overflow-hidden [mask-image:linear-gradient(90deg,transparent,#000_35%,#000_65%,transparent)] forced-colors:hidden"
          >
            <span
              ref={copyRef}
              style={{ transform: "translateX(40%)" }}
              className="absolute inset-y-0 left-0 w-[250%] text-sheen-accent"
            >
              {label}
            </span>
          </span>
        )}
      </span>
      <span ref={barsRef} aria-hidden className="flex flex-col gap-2.5">
        {[92, 74, 48].map((width) => (
          <span
            key={width}
            className="relative block h-2.5 overflow-hidden rounded-full bg-sheen-hover forced-colors:border forced-colors:border-[CanvasText]"
            style={{ width: `${width}%` }}
          >
            {!reduced && (
              <span
                data-sweep
                style={{ transform: "translateX(-100%)" }}
                className="absolute inset-y-0 left-0 w-1/2 bg-linear-to-r from-transparent via-(--sheen-glass-highlight) to-transparent"
              />
            )}
          </span>
        ))}
      </span>
    </div>
  );
}

/* ---------- Attachments ---------- */

/** A chip for one attached file: its name and size, with an optional remove button. */
export function AttachmentChip({
  attachment,
  locale,
  onRemove,
  removeLabel,
  reduced,
  appear = true,
}: {
  attachment: AiChatAttachment;
  locale: string;
  onRemove?: () => void;
  removeLabel?: string;
  reduced: boolean;
  /** Animate in on mount (off for messages that were there from the start). */
  appear?: boolean;
}) {
  const ext = attachment.name.includes(".") ? (attachment.name.split(".").pop() ?? "").toUpperCase() : "";
  const meta = [ext, attachment.size !== undefined ? formatBytes(attachment.size, locale) : ""]
    .filter(Boolean)
    .join(" · ");
  return (
    <motion.li
      layout={!reduced}
      initial={!appear ? false : reduced ? { opacity: 0 } : { opacity: 0, scale: 0.9 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={
        reduced ? { opacity: 0, transition: exitTransition } : { opacity: 0, scale: 0.92, transition: exitTransition }
      }
      transition={reduced ? { duration: duration.fast } : spring.snappy}
      className="flex max-w-60 min-w-0 items-center gap-2.5 rounded-sheen-md border border-sheen-border bg-sheen-surface/70 py-1.5 pe-1.5 ps-1.5"
    >
      {attachment.previewUrl ? (
        <img src={attachment.previewUrl} alt="" className="size-9 shrink-0 rounded-sheen-sm object-cover" />
      ) : (
        <span
          aria-hidden
          className="flex size-9 shrink-0 items-center justify-center rounded-sheen-sm bg-sheen-accent-soft text-sheen-accent"
        >
          <FileIcon className="size-4" />
        </span>
      )}
      <span className="flex min-w-0 flex-1 flex-col pe-1 text-start">
        <span className="truncate text-xs font-medium text-sheen-fg">{attachment.name}</span>
        {meta && <span className="truncate text-2xs text-sheen-fg-muted">{meta}</span>}
      </span>
      {onRemove && (
        <button
          type="button"
          onClick={onRemove}
          aria-label={removeLabel}
          className={cn(
            "relative flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-full text-sheen-fg-muted",
            "transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover hover:text-sheen-fg",
            "focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus",
            "any-pointer-coarse:after:absolute any-pointer-coarse:after:top-1/2 any-pointer-coarse:after:left-1/2 any-pointer-coarse:after:size-11 any-pointer-coarse:after:-translate-1/2",
          )}
        >
          <XIcon className="size-3.5" />
        </button>
      )}
    </motion.li>
  );
}

/* ---------- Message ---------- */

/** The callbacks the message actions need: copy, feedback and regenerate. */
export type MessageActions = {
  copy: (message: AiChatMessage) => void;
  feedback: (message: AiChatMessage, value: AiChatFeedback) => void;
  regenerate: () => void;
};

/** An icon-only action button with a tooltip and an accessible name. */
export const IconAction = ({
  label,
  onClick,
  pressed,
  children,
}: {
  label: string;
  onClick: () => void;
  pressed?: boolean;
  children: ReactNode;
}) => (
  <Tooltip content={label} delay={300}>
    <Button
      variant="ghost"
      size="icon"
      aria-label={label}
      aria-pressed={pressed}
      onClick={onClick}
      className={cn(
        "size-8 rounded-sheen-sm text-sheen-fg-muted hover:text-sheen-fg [&_svg]:size-4",
        pressed && "bg-sheen-accent-soft text-sheen-accent hover:text-sheen-accent",
        // High contrast flattens the tint: a pressed rating becomes a Highlight-filled button.
        "forced-colors:aria-pressed:forced-color-adjust-none forced-colors:aria-pressed:border-[Highlight] forced-colors:aria-pressed:bg-[Highlight] forced-colors:aria-pressed:text-[HighlightText]",
      )}
    >
      {children}
    </Button>
  </Tooltip>
);

/** Props of `MessageItem`: the message, its state and the shared labels and actions. */
export type MessageItemProps = {
  message: AiChatMessage;
  last: boolean;
  /** Animate in on mount (off for messages present from the start). */
  appear: boolean;
  copied: boolean;
  feedback: AiChatFeedback;
  modelLabel?: string;
  labels: AiChatLabels;
  locale: string;
  reduced: boolean;
  headingTag: HeadingTag;
  actions: MessageActions;
};

/** One message of the thread: the bubble or answer, its attachments and (for answers) the copy, feedback and regenerate actions. */
export const MessageItem = memo(function MessageItem({
  message,
  last,
  appear,
  copied,
  feedback,
  modelLabel,
  labels,
  locale,
  reduced,
  headingTag: Heading,
  actions,
}: MessageItemProps) {
  const enter = appear
    ? reduced
      ? { initial: { opacity: 0 }, animate: { opacity: 1 }, transition: { duration: duration.fast } }
      : {
          initial: { opacity: 0, y: 14, scale: message.role === "user" ? 0.97 : 1 },
          animate: { opacity: 1, y: 0, scale: 1 },
          // The fade is a short tween; only the movement springs (a fade that springs lingers ~900 ms).
          transition: { ...spring.smooth, opacity: { duration: duration.fast, ease: ease.out } },
        }
    : { initial: false as const };

  if (message.role === "user") {
    return (
      <motion.li {...enter} className="flex min-w-0 flex-col items-end gap-2 [transform-origin:100%_100%]">
        <Heading className="sr-only">{labels.youSaid}</Heading>
        {message.attachments && message.attachments.length > 0 && (
          <ul className="flex max-w-[85%] flex-wrap justify-end gap-2">
            {message.attachments.map((a) => (
              <AttachmentChip key={a.id} attachment={a} locale={locale} reduced={reduced} appear={appear} />
            ))}
          </ul>
        )}
        {message.content && (
          <div
            className={cn(
              "sheen-fill max-w-[85%] rounded-[1.25rem] rounded-ee-[0.375rem] px-4 py-2.5 text-[0.9375rem] leading-6 whitespace-pre-wrap text-sheen-accent-fg [overflow-wrap:anywhere] @lg:max-w-[75%]",
              "[background-image:var(--sheen-accent-fill)] shadow-[inset_0_1px_0_var(--sheen-glass-highlight),0_10px_24px_-14px_var(--sheen-accent)]",
              "forced-colors:border forced-colors:border-[CanvasText]",
            )}
          >
            {message.content}
          </div>
        )}
      </motion.li>
    );
  }

  const status = message.status ?? "done";
  const settled = status === "done" || status === "stopped";
  const working = status === "thinking" || status === "streaming";

  return (
    <motion.li {...enter} className="group/msg flex min-w-0 gap-3">
      {/* Narrow panels give the text the full width; the header still shows the status. */}
      <Orb busy={working} reduced={reduced} className="hidden @md:inline-flex" />
      <div className="flex min-w-0 flex-1 flex-col gap-2 pt-0.5">
        <Heading className="sr-only">{labels.assistantSaid(labels.assistant)}</Heading>
        {status === "thinking" ? (
          <Thinking label={labels.thinking} reduced={reduced} />
        ) : message.content ? (
          <Markdown
            text={message.content}
            streaming={status === "streaming"}
            partial={status !== "done"}
            labels={labels}
          />
        ) : status === "stopped" ? (
          <p className="text-sm leading-7 text-sheen-fg-muted italic">{labels.stoppedEarly}</p>
        ) : null}

        {status === "error" && (
          <div className="flex flex-wrap items-center gap-3 rounded-sheen-md border border-sheen-danger-text/25 bg-sheen-danger-soft px-3.5 py-2.5 text-sm text-sheen-danger-text">
            <AlertIcon className="size-4 shrink-0" />
            <span className="min-w-0 flex-1">{(message.error ?? "") || labels.errorFallback}</span>
            {last && (
              <Button
                variant="glass"
                size="sm"
                onClick={actions.regenerate}
                leading={<RetryIcon className="size-3.5" />}
              >
                {labels.retry}
              </Button>
            )}
          </div>
        )}

        {settled && (
          <div
            className={cn(
              "-ms-1.5 flex flex-wrap items-center gap-0.5 any-pointer-coarse:gap-3",
              // Older replies show their actions on hover or focus (always on touch screens).
              !last &&
                "opacity-0 transition-opacity duration-(--sheen-duration-fast) group-hover/msg:opacity-100 group-focus-within/msg:opacity-100 any-pointer-coarse:opacity-100",
            )}
          >
            {message.content && (
              <IconAction label={copied ? labels.copied : labels.copy} onClick={() => actions.copy(message)}>
                {copied ? <CheckIcon /> : <CopyIcon />}
              </IconAction>
            )}
            {message.content && (
              <>
                <IconAction
                  label={labels.goodResponse}
                  pressed={feedback === "up"}
                  onClick={() => actions.feedback(message, feedback === "up" ? null : "up")}
                >
                  <ThumbIcon filled={feedback === "up"} />
                </IconAction>
                <IconAction
                  label={labels.badResponse}
                  pressed={feedback === "down"}
                  onClick={() => actions.feedback(message, feedback === "down" ? null : "down")}
                >
                  <ThumbIcon down filled={feedback === "down"} />
                </IconAction>
              </>
            )}
            {last && (
              <IconAction label={labels.regenerate} onClick={actions.regenerate}>
                <RetryIcon />
              </IconAction>
            )}
            {(status === "stopped" && message.content) || modelLabel ? (
              <span className="ms-1.5 flex items-center gap-1.5 text-2xs font-medium text-sheen-fg-muted">
                {status === "stopped" && message.content && (
                  <span className="inline-flex items-center gap-1">
                    <StopIcon className="size-2.5" />
                    {labels.stopped}
                  </span>
                )}
                {status === "stopped" && message.content && modelLabel && <span aria-hidden>·</span>}
                {modelLabel}
              </span>
            ) : null}
          </div>
        )}
      </div>
    </motion.li>
  );
});

import type { HeadingLevelOption } from "../../lib/heading";
/* ---------- Types ---------- */

/** Who wrote a message: the person (`"user"`) or the assistant (`"assistant"`). */
export type AiChatRole = "user" | "assistant";

/** "thinking" until the first words arrive, then "streaming", then one of the end states. */
export type AiChatStatus = "thinking" | "streaming" | "done" | "stopped" | "error";

/** A file attached to a message: its name, optional size in bytes, MIME type, preview URL and (for files picked in this session) the `File` itself. */
export type AiChatAttachment = {
  id: string;
  name: string;
  /** Size in bytes. */
  size?: number;
  /** MIME type, e.g. "image/png". */
  type?: string;
  /** Thumbnail URL for images. Object URLs the block creates are revoked when it unmounts. */
  previewUrl?: string;
  /** The picked file (attachments added in this session). */
  file?: File;
};

/** One message of the conversation: author role, light-Markdown `content`, optional attachments and model, and (assistant messages) the reply status and error text. */
export type AiChatMessage = {
  id: string;
  role: AiChatRole;
  /** Light Markdown: **bold**, `code`, ``` fenced blocks ```, - lists, 1. lists, [links](https://…). */
  content: string;
  attachments?: AiChatAttachment[];
  /** Value of the model that wrote an assistant message. */
  model?: string;
  /** Assistant messages only. Left out = "done". */
  status?: AiChatStatus;
  /** Shown when status is "error". */
  error?: string;
};

/** A model the person can pick: the `value` sent with requests, the display `label` and an optional one-line `description`. */
export type AiChatModel = { value: string; label: string; description?: string };

/** What an `AiChatRespond` handler receives: the prompt, attachments, the conversation so far, the chosen model, the regeneration attempt number and an abort signal. */
export type AiChatRequest = {
  prompt: string;
  attachments: AiChatAttachment[];
  /** The conversation so far, oldest first, ending with this prompt. */
  messages: AiChatMessage[];
  model: string;
  /** 0 for a new prompt; 1, 2… each time the reply is regenerated. */
  attempt: number;
  /** Aborted when the person presses Stop, starts a new chat or the block unmounts. */
  signal: AbortSignal;
};

/** Return the whole reply (typed out for you) or an async iterable of chunks (real streaming). */
export type AiChatRespond = (request: AiChatRequest) => string | Promise<string> | AsyncIterable<string>;

/** A thumbs rating on an assistant reply: `"up"`, `"down"`, or `null` when the rating was cleared. */
export type AiChatFeedback = "up" | "down" | null;

/** Every user-facing string, so the block can be translated. */
export type AiChatLabels = {
  /** The assistant's name, shown in the header. */
  assistant: string;
  online: string;
  thinking: string;
  writing: string;
  newChat: string;
  /** Accessible name of the scrolling conversation. */
  conversation: string;
  /** Hidden heading before each of the person's messages. */
  youSaid: string;
  /** Hidden heading before each reply; receives the assistant's name. */
  assistantSaid: (assistant: string) => string;
  emptyTitle: string;
  emptyDescription: string;
  /** Accessible name of the suggestion list. The default is sample content for demos and prototypes: pass your own in production. The default is sample content for demos and prototypes: pass your own in production. */
  suggestions: string;
  /** Label of the message field (visually hidden). */
  message: string;
  placeholder: string;
  /** How to send with a keyboard. */
  keyHint: string;
  /** The same for touch keyboards, where Enter adds a line. */
  keyHintTouch: string;
  /** Small print under the composer. Empty string hides it. */
  disclaimer: string;
  send: string;
  stop: string;
  attach: string;
  /** Accessible name of the pending attachments list. */
  attachments: string;
  removeAttachment: (name: string) => string;
  attached: (names: string[]) => string;
  removed: (name: string) => string;
  /** Shown (and announced) when more files are picked than fit. */
  tooManyFiles: (max: number) => string;
  dropFiles: string;
  model: string;
  scrollToBottom: string;
  copy: string;
  copied: string;
  copyFailed: string;
  /** Header of a code block without a language. */
  code: string;
  /** Accessible name of a code block, also read in place of its code when a reply is announced; receives its language ("" when unknown). */
  codeRegion: (language: string) => string;
  copyCode: string;
  goodResponse: string;
  badResponse: string;
  feedbackThanks: string;
  regenerate: string;
  /** Under a reply that was stopped part way. */
  stopped: string;
  /** In place of a reply stopped before it began. */
  stoppedEarly: string;
  errorFallback: string;
  retry: string;
  /** Live announcements. */
  thinkingAnnouncement: string;
  /** Receives the reply as plain text (code blocks named, not read; long replies cut short). */
  replied: (assistant: string, text: string) => string;
  /** Ends an announcement that was cut short. */
  replyContinues: string;
  stoppedAnnouncement: string;
  cleared: string;
};

/** Props of `AiChat`. Everything is optional: with none it plays canned demo replies. */
export type AiChatProps = {
  /** Produces the reply (`AiChatRespond`). Returns a string (typed out for you), a promise of one, or an async iterable of chunks (real streaming). Defaults to canned demo replies. The default is sample content for demos and prototypes: pass your own in production. The default is sample content for demos and prototypes: pass your own in production. */
  respond?: AiChatRespond;
  /** Conversation to start with (shown without animation). */
  defaultMessages?: AiChatMessage[];
  /**
   * The conversation (controlled). Passing a new array replaces what is shown (load history, switch threads) without
   * animation and stops a reply in progress. Keep it in sync with `onMessagesChange`; leave it out to let the chat own it.
   */
  messages?: AiChatMessage[];
  /** Show the assistant's "thinking" row although no reply is running here, for chats whose replies come from your own backend (controlled `messages`). */
  isTyping?: boolean;
  /** Called with the whole conversation whenever it settles: a reply ends, stops or fails, or the chat is cleared. */
  onMessagesChange?: (messages: AiChatMessage[]) => void;
  /** Called when the person sends a message. */
  onSend?: (message: AiChatMessage) => void;
  /** Called when a reply is rated (null = rating removed). */
  onFeedback?: (message: AiChatMessage, feedback: AiChatFeedback) => void;
  /** Models for the picker; the picker hides with fewer than two. The default is sample content for demos and prototypes: pass your own in production. The default is sample content for demos and prototypes: pass your own in production. */
  models?: AiChatModel[];
  /** Sets the selected model's `value` when controlled. */
  model?: string;
  /** The model selected at first when `model` is not controlled; the first of `models` when omitted. */
  defaultModel?: string;
  /** Called when another model is picked. */
  onModelChange?: (model: string) => void;
  /** Prompts offered as chips while the chat is empty. */
  suggestions?: string[];
  /** Show the attach button and accept dropped files. */
  allowAttachments?: boolean;
  /** `accept` for the file picker, e.g. "image/*,.pdf". */
  accept?: string;
  /** Most files one message can carry. */
  maxAttachments?: number;
  /** Type out string replies word by word (turn it off to show them whole). Streams are never delayed. */
  simulateStreaming?: boolean;
  /** Characters per second for the typed-out reply. */
  typingSpeed?: number;
  /** Shortest "thinking" time (ms) before a string reply starts, so it never flashes. */
  thinkingDelay?: number;
  /** Tallest the message field grows, in lines, before it scrolls. */
  maxRows?: number;
  /** Heading level of the assistant name; message headings are one level below. `"none"` renders them all as paragraphs with no heading role (for an example). */
  headingLevel?: HeadingLevelOption;
  /** Focus the message field on mount. Off by default: only use it when the chat is the page's main task. */
  autoFocus?: boolean;
  /** BCP 47 locale for file sizes. */
  locale?: string;
  /** Overrides for the built-in English strings (`Partial<AiChatLabels>`). */
  labels?: Partial<AiChatLabels>;
  /** Classes for the outer glass panel (set its height here). */
  className?: string;
};

import { type AiChatLabels } from "./types";
import { parseBlocks } from "./markdown";

/* ---------- Small utilities ---------- */

/** Creates the `AbortError` a cancelled request rejects with. */
export function abortError() {
  return new DOMException("Aborted", "AbortError");
}

/** Resolves with `promise`, or rejects as soon as `signal` aborts. */
export function abortable<T>(promise: PromiseLike<T>, signal: AbortSignal): Promise<T> {
  if (signal.aborted) return Promise.reject(abortError());
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => reject(abortError());
    signal.addEventListener("abort", onAbort, { once: true });
    Promise.resolve(promise).then(
      (value) => {
        signal.removeEventListener("abort", onAbort);
        resolve(value);
      },
      (error: unknown) => {
        signal.removeEventListener("abort", onAbort);
        // Anything that is not an Error carries no message (the reply then shows the fallback text).
        reject(error instanceof Error ? error : new Error("", { cause: error }));
      },
    );
  });
}

/** Resolves after `ms` milliseconds, or rejects with an abort error when the signal fires first. */
export function sleep(ms: number, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal.aborted) {
      reject(abortError());
      return;
    }
    const onAbort = () => {
      window.clearTimeout(timer);
      reject(abortError());
    };
    const timer = window.setTimeout(() => {
      signal.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

/** True when a value is an async iterable of strings (a streamed reply). */
export function isAsyncIterable(value: unknown): value is AsyncIterable<string> {
  return value != null && typeof (value as AsyncIterable<string>)[Symbol.asyncIterator] === "function";
}

/** Inline Markdown markers stripped: what a screen reader should hear. */
export function plainInline(text: string) {
  return text
    .replace(/\*\*/g, "")
    .replace(/`/g, "")
    .replace(/\[([^\]\n]+)\]\([^)\s]+\)/g, "$1")
    .trim();
}

/** Longest announcement before it is cut short (at a word boundary). */
export const ANNOUNCE_MAX = 300;

/**
 * A finished reply as one short announcement: plain text, each code block named
 * ("Code, tsx") instead of read line by line, and cut short after about 300 characters.
 */
export function toAnnouncement(markdown: string, labels: AiChatLabels) {
  const parts = parseBlocks(markdown).map((block) => {
    switch (block.type) {
      case "code":
        return `${labels.codeRegion(block.lang)}.`;
      case "h":
        return plainInline(block.text);
      case "ul":
      case "ol":
        return block.items.map(plainInline).join("; ");
      default:
        return block.lines.map(plainInline).join(" ");
    }
  });
  const text = parts.filter(Boolean).join(" ").replace(/\s+/g, " ").trim();
  if (text.length <= ANNOUNCE_MAX) return text;
  const cut = text.slice(0, ANNOUNCE_MAX);
  const space = cut.lastIndexOf(" ");
  return `${(space > ANNOUNCE_MAX * 0.6 ? cut.slice(0, space) : cut).replace(/[\s,.;:]+$/, "")}… ${labels.replyContinues}`;
}

/** Formats a byte count for display in the given locale (for example "1.2 MB"). */
export function formatBytes(bytes: number, locale: string) {
  const mb = bytes >= 1_000_000;
  return new Intl.NumberFormat(locale, {
    style: "unit",
    unit: mb ? "megabyte" : "kilobyte",
    unitDisplay: "short",
    maximumFractionDigits: mb ? 1 : 0,
  }).format(Math.max(mb ? bytes / 1_000_000 : bytes / 1000, mb ? 0 : 1));
}

